import * as React from "react"
import { Link, navigate } from "gatsby"
import Seo from "../components/Seo"
import AuthShell from "../components/auth/AuthShell"
import { ArrowRight } from "../components/Icons"
import { NOT_CONFIGURED, configured } from "../lib/supabase"
import { useAuth } from "../context/auth"
import * as s from "../components/auth/Auth.module.css"

/**
 * The account screen, and the only signed-in-only page — MTC-FCS-008.
 *
 * ── IT WAITS FOR `ready` BEFORE DECIDING ANYTHING ──────────────────────────
 * Restoring a session is asynchronous. Redirecting on `!user` alone bounces a
 * signed-in visitor to the login page for the split second before their
 * session loads, and they land back here a moment later having watched the
 * page flash. Waiting costs one frame and removes that entirely.
 *
 * ── SIGNING OUT IS A REAL SIGN OUT ─────────────────────────────────────────
 * It clears the Supabase session rather than just forgetting it locally, so a
 * shared machine does not keep a refreshable token lying around.
 */
const AccountPage = () => {
  const { user, ready, signOut, available } = useAuth()

  React.useEffect(() => {
    if (ready && available && !user) navigate("/log-in?next=/account", { replace: true })
  }, [ready, available, user])

  if (!configured()) {
    return (
      <AuthShell title="Your account" notice={NOT_CONFIGURED}>
        <p className={s.lead}>Accounts cannot be used on this environment yet.</p>
      </AuthShell>
    )
  }

  if (!ready || !user) {
    return (
      <AuthShell title="Your account">
        <p className={s.loading}>Loading…</p>
      </AuthShell>
    )
  }

  const created = user.created_at ? new Date(user.created_at).toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  }) : ""

  return (
    <AuthShell title="Your account" lead="Your details and what you can do next.">
      <div className={s.rows}>
        <div className={s.row}>
          <span>Email</span>
          <span>{user.email}</span>
        </div>
        {created ? (
          <div className={s.row}>
            <span>Member since</span>
            <span>{created}</span>
          </div>
        ) : null}
        <div className={s.row}>
          <span>Email confirmed</span>
          <span>{user.email_confirmed_at ? "Yes" : "Not yet — check your inbox"}</span>
        </div>
      </div>

      <div className={s.actions}>
        <Link to="/website-builder" className="btn btn--lg">
          My website
          <ArrowRight className="btn__arrow" />
        </Link>
        <Link to="/invoice-builder" className={s.signOut} style={{ textDecoration: "none" }}>
          Invoices
        </Link>
        <button type="button" className={s.signOut} onClick={() => signOut().then(() => navigate("/"))}>
          Log out
        </button>
      </div>
    </AuthShell>
  )
}

export const Head = () => <Seo title="Your account" />

export default AccountPage
